import static org.junit.Assert.*;

public class Element_previousElementSibling_TriageGen2Test {





    @Test
    public void testPreviousElementSibling_TwoElements_ReturnsFirstElement() {
        Document doc = new Document("<html><body><p></p><p></p></body></html>");
        Element element = doc.body().getElementsByTag("p").get(1);
        assertEquals(doc.body().getElementsByTag("p").get(0), element.previousElementSibling());
    }








}

